"""
Integration Testing Script

Tests all 5 SaaS product endpoints to verify your LLM
integrations are working correctly.

Usage:
    python test_integrations.py

Make sure your integration APIs are running:
    - ProseAI:    http://localhost:8001
    - DocMind:    http://localhost:8002
    - PixelForge: http://localhost:8003
    - TruthLens:  http://localhost:8004
    - ClipCraft:  http://localhost:8005
"""

import httpx
import json
import sys
from typing import Dict, Any


# ── Configuration ────────────────────────────────────────────────
ENDPOINTS = {
    "ProseAI": {
        "base_url": "http://localhost:8001",
        "tests": [
            {
                "name": "Rewrite (formal)",
                "method": "POST",
                "path": "/api/rewrite",
                "body": {
                    "text": "Hey, the new update is super cool "
                            "and works great!",
                    "mode": "formal",
                },
                "expect_keys": ["rewritten", "mode",
                                "model_used"],
            },
            {
                "name": "Rewrite (concise)",
                "method": "POST",
                "path": "/api/rewrite",
                "body": {
                    "text": "In order to facilitate the "
                            "implementation of the new system, "
                            "it would be beneficial to conduct "
                            "a comprehensive review.",
                    "mode": "concise",
                },
                "expect_keys": ["rewritten"],
            },
            {
                "name": "Analyze style",
                "method": "POST",
                "path": "/api/analyze-style",
                "body": {
                    "text": "Machine learning enables computers "
                            "to learn from data without being "
                            "explicitly programmed.",
                },
                "expect_keys": ["analysis"],
            },
        ],
    },
    "DocMind": {
        "base_url": "http://localhost:8002",
        "tests": [
            {
                "name": "Ask question",
                "method": "POST",
                "path": "/api/ask",
                "body": {
                    "document": "Annual Report 2024: Revenue "
                                "was $4.2M, up 35% from 2023. "
                                "Operating expenses decreased "
                                "by 12% to $2.8M.",
                    "question": "What was the revenue?",
                },
                "expect_keys": ["answer", "model_used"],
            },
            {
                "name": "Summarize",
                "method": "POST",
                "path": "/api/summarize",
                "body": {
                    "document": "The company launched three new "
                                "products in Q3. Product A "
                                "targets enterprise customers. "
                                "Product B serves SMBs. "
                                "Product C is for consumers.",
                    "detail_level": "brief",
                },
                "expect_keys": ["summary"],
            },
            {
                "name": "Extract data",
                "method": "POST",
                "path": "/api/extract",
                "body": {
                    "document": "Invoice #1234. Date: 2024-01-15. "
                                "Amount: $500. Client: Acme Corp.",
                    "fields": ["invoice_number", "date",
                               "amount", "client"],
                },
                "expect_keys": ["extracted"],
            },
        ],
    },
    "PixelForge": {
        "base_url": "http://localhost:8003",
        "tests": [
            {
                "name": "Enhance prompt",
                "method": "POST",
                "path": "/api/enhance-prompt",
                "body": {
                    "prompt": "a cat on a roof",
                    "style": "photograph",
                },
                "expect_keys": ["enhanced_prompt"],
            },
        ],
    },
    "TruthLens": {
        "base_url": "http://localhost:8004",
        "tests": [
            {
                "name": "Analyze text",
                "method": "POST",
                "path": "/api/analyze",
                "body": {
                    "text": "Machine learning is a subset of AI. "
                            "It enables computers to learn from "
                            "data. This is very important.",
                },
                "expect_keys": ["analysis"],
            },
        ],
    },
    "ClipCraft": {
        "base_url": "http://localhost:8005",
        "tests": [
            {
                "name": "Generate script",
                "method": "POST",
                "path": "/api/generate-script",
                "body": {
                    "concept": "A 30-second product intro for "
                               "a mobile app",
                    "duration": 30,
                },
                "expect_keys": ["script"],
            },
        ],
    },
}


# ── Test Runner ──────────────────────────────────────────────────
def run_test(product: str, base_url: str,
             test: Dict[str, Any]) -> bool:
    """Run a single test and return True if passed."""
    url = f"{base_url}{test['path']}"
    name = test["name"]

    try:
        with httpx.Client(timeout=30.0) as client:
            if test["method"] == "POST":
                response = client.post(url, json=test["body"])
            else:
                response = client.get(url)

        if response.status_code != 200:
            print(f"  FAIL {name}: HTTP {response.status_code}")
            print(f"        {response.text[:200]}")
            return False

        data = response.json()

        # Check expected keys
        missing = [k for k in test.get("expect_keys", [])
                   if k not in data]
        if missing:
            print(f"  FAIL {name}: Missing keys: {missing}")
            return False

        print(f"  PASS {name}")
        # Show a preview of the response
        preview = json.dumps(data, indent=2)[:200]
        print(f"       Response: {preview}...")
        return True

    except httpx.ConnectError:
        print(f"  SKIP {name}: Cannot connect to {base_url}")
        return False
    except Exception as e:
        print(f"  FAIL {name}: {e}")
        return False


def main():
    """Run all integration tests."""
    print("=" * 60)
    print("GenAI SaaS Integration Tests")
    print("=" * 60)

    total = 0
    passed = 0
    skipped = 0

    for product, config in ENDPOINTS.items():
        print(f"\n--- {product} ({config['base_url']}) ---")

        # Health check first
        try:
            with httpx.Client(timeout=5.0) as client:
                r = client.get(f"{config['base_url']}/health")
                if r.status_code == 200:
                    health = r.json()
                    llm_status = health.get(
                        "llm_reachable", "unknown")
                    print(f"  Health: OK "
                          f"(LLM reachable: {llm_status})")
                else:
                    print(f"  Health: HTTP {r.status_code}")
        except httpx.ConnectError:
            print(f"  Health: Cannot connect — "
                  f"is the server running?")
            skipped += len(config["tests"])
            total += len(config["tests"])
            continue

        # Run tests
        for test in config["tests"]:
            total += 1
            if run_test(product, config["base_url"], test):
                passed += 1

    # Summary
    failed = total - passed - skipped
    print(f"\n{'=' * 60}")
    print(f"Results: {passed}/{total} passed, "
          f"{failed} failed, {skipped} skipped")
    print(f"{'=' * 60}")

    if failed > 0:
        sys.exit(1)


if __name__ == "__main__":
    main()
